INSERT INTO public.knowledge_articles (title, content, summary, category, emoji, read_time_minutes, tags, thumbnail_url, is_published, author_name, view_count, created_at, updated_at)
SELECT * FROM (VALUES
('The Bond Between Parrots: Social Needs', 'Parrots are incredibly social creatures that live in large flocks in the wild. A solitary bird often looks to its human as its ''mate,'' which can lead to behavioral issues and aggression. If you cannot spend several hours a day with your bird, consider a same-species companion. However, introductions must be slow to ensure they don''t fight over territory.', 'Why most parrots should not be kept in solitary confinement.', 'Avian', '👯', 9, ARRAY['birds','behavior','life','bonding']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:30:00Z'::timestamptz, '2026-05-14T10:30:00Z'::timestamptz),
('UV Lighting for Birds: Is It Necessary?', 'Birds need UVA and UVB light to synthesize Vitamin D3, which is crucial for calcium absorption. Since window glass filters out most UV rays, indoor birds often become deficient. Specialized avian UV lamps can improve feather quality, mood, and prevent metabolic bone disease. Ensure the lamp is placed at the correct distance to avoid eye damage and follow a strict on/off cycle.', 'Understanding Vitamin D3 synthesis and its impact on avian health.', 'Avian', '☀️', 8, ARRAY['birds','health','setup','safety']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:35:00Z'::timestamptz, '2026-05-14T10:35:00Z'::timestamptz),
('Reptile Brumation: What to Expect', 'Brumation is the reptile equivalent of hibernation. During colder months, your pet may stop eating and sleep for weeks. It’s a natural biological process triggered by seasonal changes. Before letting them settle, a vet visit is recommended to ensure they don''t have underlying parasites, which can become dangerous while their immune system is dormant.', 'Understanding the ''winter slowdown'' for bearded dragons and turtles.', 'Small Pet', '💤', 7, ARRAY['reptiles','behavior','health','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:40:00Z'::timestamptz, '2026-05-14T10:40:00Z'::timestamptz),
('Sugar Glider Social Structures', 'Sugar gliders are colony animals. Keeping a single glider can lead to self-mutilation and severe depression due to loneliness. They require the company of their own kind to groom, sleep, and communicate. If you are considering a sugar glider, you must commit to at least a pair to ensure their mental well-being and natural social development.', 'Why these ''pocket pets'' can never be kept alone.', 'Small Pet', '🐿️', 8, ARRAY['small pets','behavior','life','bonding']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:45:00Z'::timestamptz, '2026-05-14T10:45:00Z'::timestamptz),
('Pet Microchip Databases: Staying Updated', 'A microchip is useless if it''s linked to an old phone number or an address you no longer live at. Every time you move or change your number, you must update the national registry. Many shelters find ''chipped'' pets but can''t reunite them because the data is obsolete. Set a yearly reminder to check your pet''s registry status to ensure they always have a way home.', 'The chip is only half the battle—why your contact info matters.', 'General', '🏷️', 5, ARRAY['safety','life','maintenance','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:50:00Z'::timestamptz, '2026-05-14T10:50:00Z'::timestamptz),
('Flea and Tick Prevention: Chemical vs. Natural', 'Traditional spot-on treatments and collars are highly effective but can occasionally cause skin sensitivity. Natural alternatives like neem oil or cedar sprays can repel pests but often fail to kill an existing infestation. In tropical climates, where fleas are active year-round, a combination of environmental cleaning and vet-approved preventative is usually the safest and most effective route.', 'Evaluating the efficacy and safety of different pest control methods.', 'General', '🪲', 9, ARRAY['health','safety','maintenance','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:55:00Z'::timestamptz, '2026-05-14T10:55:00Z'::timestamptz),
('Dewclaw Care: Why You Shouldn''t Ignore Them', 'The dewclaw is the extra nail on the inner side of a dog''s paw. Since it doesn''t touch the ground, it doesn''t wear down naturally like other nails. If left untrimmed, it can curl back and pierce the skin or get snagged on carpets and upholstery, causing painful tears. Check them every two weeks and keep them short to avoid emergency vet trips for ''torn dewclaws.''', 'Preventing painful snags and ingrown nails on your dog''s ''thumb.''', 'Canine', '🐾', 5, ARRAY['dogs','grooming','health','maintenance']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:00:00Z'::timestamptz, '2026-05-14T22:00:00Z'::timestamptz),
('Canine Cognitive Dysfunction (CCD): Senior Care', 'CCD is common in dogs over age 10. Signs include pacing at night, getting stuck in corners, or forgetting house training. While it can''t be cured, certain supplements (like Omega-3s) and keeping a strict routine can reduce confusion. Mental stimulation through gentle puzzle toys also helps keep their brain active. Early intervention is key to maintaining their quality of life.', 'Understanding ''doggy dementia'' and how to support your aging companion.', 'Canine', '🧠', 9, ARRAY['dogs','senior care','health','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:05:00Z'::timestamptz, '2026-05-14T22:05:00Z'::timestamptz),
('Why Cats Scratch Near Their Food', 'If your cat scratches the floor around their bowl after eating, they are performing a ''caching'' behavior. In the wild, cats bury their leftovers to hide the scent from predators. Even though there''s no dirt on your kitchen tile, the instinct remains. It’s a sign they are finished and want to ''save'' the rest—or simply a biological quirk you shouldn''t worry about.', 'Decoding the ''caching'' instinct and what it means for your floor.', 'Feline', '🥣', 4, ARRAY['cats','behavior','life','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:10:00Z'::timestamptz, '2026-05-14T22:10:00Z'::timestamptz),
('The Dangers of Strings and Yarn for Cats', 'Cats love to play with string, but their barbed tongues make it nearly impossible to spit out. If swallowed, the string can cause the intestines to ''bunch up'' like a drawstring bag, leading to fatal perforations. Never let your cat play with yarn or dental floss unsupervised. If you see a string under their tongue or protruding from their rear, **NEVER** pull it—rush to a vet immediately.', 'Why linear foreign bodies are one of the most dangerous surgical emergencies.', 'Feline', '🧶', 8, ARRAY['cats','safety','health','emergency']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:15:00Z'::timestamptz, '2026-05-14T22:15:00Z'::timestamptz),
('Betta Fish Sororities: High Risk, High Reward?', 'A ''Sorority'' is a group of female Bettas kept in one tank. While beautiful, it is an advanced setup that requires a minimum of 20 gallons and heavy planting to break lines of sight. Aggression is always a risk. You must have a ''Plan B'' (separate tanks) ready for every fish if the hierarchy fails. It is not recommended for beginners due to the high stress levels for the fish.', 'Understanding the complex dynamics of keeping female Bettas together.', 'Aquatic', '🐠', 11, ARRAY['aquarium','behavior','species','safety']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:20:00Z'::timestamptz, '2026-05-14T22:20:00Z'::timestamptz),
('Controlling Hair Algae in Your Aquascape', 'Hair algae usually signals an imbalance between light and nutrients. Manual removal with a toothbrush is the first step. For biological control, Amano Shrimp and Siamese Algae Eaters (SAE) are the most effective. Ensure you don''t overfeed, as these animals will only eat algae if they aren''t full of fish food. Reducing your ''lights-on'' time to 6 hours can also help starve the algae out.', 'Why this stringy nuisance appears and how to use ''Algae Eaters'' effectively.', 'Aquatic', '🕸️', 7, ARRAY['aquarium','maintenance','plants','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:25:00Z'::timestamptz, '2026-05-14T22:25:00Z'::timestamptz),
('Signs of Arthritis in Senior Birds', 'Older birds may develop arthritis, making it hard for them to grip thin perches. If your bird is spending more time on the cage floor or seems unsteady, swap narrow dowels for wide, flat ''platform perches.'' Lower the food and water dishes so they don''t have to climb high. Softening the cage floor with paper towels can also provide a cushion if they happen to lose their balance.', 'How to adapt a cage for a bird with stiff joints and mobility issues.', 'Avian', '🕊️', 10, ARRAY['birds','senior care','health','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:30:00Z'::timestamptz, '2026-05-14T22:30:00Z'::timestamptz),
('Egg Binding in Small Birds: A Critical Warning', 'Egg binding is a life-threatening emergency common in budgies and cockatiels. Symptoms include sitting puffed up on the floor, heavy breathing, and a swollen abdomen. This is often caused by calcium deficiency. If you suspect your bird is egg-bound, keep them warm and humid (a steamy bathroom can help) and contact an avian vet immediately. Never attempt to remove the egg yourself.', 'Recognizing when a female bird is unable to pass an egg.', 'Avian', '🥚', 6, ARRAY['birds','health','safety','emergency']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:35:00Z'::timestamptz, '2026-05-14T22:35:00Z'::timestamptz),
('Hermit Crab Shell Selection: The ''Move-In'' Guide', 'Hermit crabs need to change shells as they grow. Never buy ''painted'' shells; the paint can chip off and poison the crab. Instead, provide a variety of natural turbo or babylonia shells in different sizes. A rule of thumb is to have 3-5 empty shells per crab in the enclosure. This prevents ''shell fights'' between crabs and ensures they always have a comfortable, safe home.', 'Why painted shells are toxic and how to provide natural options.', 'Small Pet', '🐚', 7, ARRAY['small pets','setup','safety','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:40:00Z'::timestamptz, '2026-05-14T22:40:00Z'::timestamptz),
('The ''Wet Tail'' Myth in Hamsters', '''Wet Tail'' is a severe bacterial infection often triggered by stress in young hamsters. It causes extreme diarrhea, lethargy, and a hunched posture. It is highly contagious and often fatal within 48 hours without antibiotics. If you see a soiled tail area, do not wait—hydration and veterinary care are the only way to save a hamster with this condition.', 'Understanding Proliferative Ileitis and why it''s more than just diarrhea.', 'Small Pet', '🐹', 6, ARRAY['hamsters','health','safety','emergency']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:45:00Z'::timestamptz, '2026-05-14T22:45:00Z'::timestamptz),
('Pet Microchip Migration: Why You Can''t Feel It', 'Microchips are designed to stay in the loose skin between the shoulder blades, but they can occasionally ''migrate'' to the side or chest. This doesn''t hurt the pet, but it’s why professional scanners are moved across the entire body. If you''re doing a home check, don''t panic if you can''t feel the ''grain of rice'' in the original spot; a vet''s scanner will still pick up the signal.', 'Why your vet scans the whole body, not just the shoulders.', 'General', '📡', 5, ARRAY['safety','health','life','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:50:00Z'::timestamptz, '2026-05-14T22:50:00Z'::timestamptz),
('Boarding vs. Pet Sitting: Which is Best?', 'Choosing between a kennel and a pet sitter depends on your pet''s personality. Social dogs often thrive in high-activity boarding facilities, while anxious dogs or cats usually prefer staying in their own environment with a professional sitter. Always ask for references, check for current vaccination requirements, and do a ''trial run'' overnight before a long trip to see how your pet adjusts.', 'Evaluating the stress levels and safety of different vacation care options.', 'General', '🏨', 8, ARRAY['life','safety','travel','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:55:00Z'::timestamptz, '2026-05-14T22:55:00Z'::timestamptz),
('The ''Zoomies'': Why Dogs Get Sudden Bursts of Energy', 'The ''zoomies'' are a natural way for dogs to release pent-up energy or stress. You might notice them after a bath, a long nap, or a walk. While they look wild, they are completely normal. Ensure your dog is in a safe, non-slip area when the energy hits. If they happen frequently, it may be a sign your dog needs more structured daily exercise or mental stimulation.', 'Understanding Frenetic Random Activity Periods (FRAPs).', 'Canine', '🏎️', 5, ARRAY['dogs','behavior','life','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T09:00:00Z'::timestamptz, '2026-05-15T09:00:00Z'::timestamptz),
('Bloat in Large Breeds: A Life-Saving Guide', 'Bloat is a condition where the stomach fills with gas and twists. It is a top-tier emergency. Symptoms include unproductive retching, a hard/swollen abdomen, and extreme restlessness. Deep-chested breeds are most at risk. To help prevent it, avoid vigorous exercise 1 hour before and after meals, and consider using slow-feeder bowls to reduce the amount of air swallowed during eating.', 'Recognizing Gastric Dilatation-Volvulus (GDV) before it''s too late.', 'Canine', '🚨', 10, ARRAY['dogs','health','safety','emergency']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T09:05:00Z'::timestamptz, '2026-05-15T09:05:00Z'::timestamptz),
('Why Cats Love High Places', 'In the wild, cats are both predators and prey. Being high up gives them a strategic vantage point to spot ''prey'' (like a feather toy) and safety from larger ground-based ''predators.'' If your cat is stressed, providing vertical space like a cat tree or shelving can significantly increase their confidence. It allows them to observe the room without feeling vulnerable to foot traffic.', 'The evolutionary logic behind your cat''s obsession with the fridge.', 'Feline', '🗼', 6, ARRAY['cats','behavior','setup','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T09:10:00Z'::timestamptz, '2026-05-15T09:10:00Z'::timestamptz),
('The Importance of Taurine in Cat Food', 'Unlike dogs or humans, cats cannot synthesize taurine in their bodies. Taurine is only found in animal proteins. A deficiency can lead to dilated cardiomyopathy (heart failure) and permanent blindness. This is why ''vegan'' diets are dangerous for felines. Always ensure your cat''s food is labeled as ''complete and balanced,'' which guarantees the correct taurine levels for their survival.', 'Why cats cannot be vegetarians and the science of essential amino acids.', 'Feline', '🥩', 8, ARRAY['cats','nutrition','health','science']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T09:15:00Z'::timestamptz, '2026-05-15T09:15:00Z'::timestamptz),
('CO2 Injection in Aquascaping: The Basics', 'Plants need CO2 for photosynthesis. In a heavily planted tank, natural CO2 isn''t enough for ''carpet'' plants to thrive. Pressurized CO2 systems can create lush growth, but they must be balanced. Too much CO2 will lower the pH and starve your fish of oxygen. Use a ''drop checker''—a visual indicator that turns green when levels are safe—and always turn the CO2 off at night when plants aren''t using it.', 'How to turbo-charge plant growth without suffocating your fish.', 'Aquatic', '🧪', 12, ARRAY['aquarium','plants','setup','maintenance']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T09:20:00Z'::timestamptz, '2026-05-15T09:20:00Z'::timestamptz),
('Shrimp Molting Issues: The White Ring of Death', 'The ''White Ring of Death'' occurs when a shrimp''s shell splits but they cannot escape it, eventually leading to death. This is usually caused by improper water hardness (GH/KH). If the water is too soft, the shell is too weak; if too hard, it’s too tough to break. Ensuring a steady mineral supply through high-quality shrimp minerals and consistent water parameters is the best way to keep your colony healthy.', 'Diagnosing and preventing failed molts in Dwarf Shrimp.', 'Aquatic', '🦐', 7, ARRAY['aquarium','maintenance','species','health']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T09:25:00Z'::timestamptz, '2026-05-15T09:25:00Z'::timestamptz),
('Why Your Bird is Screaming', 'Birds are naturally loud, especially at sunrise and sunset. However, excessive screaming can be a sign of boredom, fear, or a desire for attention. If you react every time your bird screams, you are ''rewarding'' the behavior. Instead, reward quiet play or ''talking'' noises. Ensure they have plenty of foraging toys to keep their beaks busy and prevent the frustration that leads to vocal outbursts.', 'Differentiating between ''happy noise'' and ''distress calls.''', 'Avian', '📢', 9, ARRAY['birds','behavior','training','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T09:30:00Z'::timestamptz, '2026-05-15T09:30:00Z'::timestamptz),
('Safe vs. Toxic Woods for Bird Perches', 'Natural branches are better for bird feet than uniform dowels, but not all wood is safe. Avoid cherry, oak, and any wood from evergreen trees that leak sap. Safe options include apple, manzanita, and grapevine. Before placing found wood in a cage, scrub it with vinegar and water, and bake it in the oven at a low temp to kill any wild parasites or bacteria.', 'How to forage for natural perches without poisoning your pet.', 'Avian', '🪵', 8, ARRAY['birds','setup','safety','maintenance']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T09:35:00Z'::timestamptz, '2026-05-15T09:35:00Z'::timestamptz),
('Rabbits and Carrots: The Sugar Myth', 'Carrots are very high in sugar and should only be given as a rare treat, not a staple. A rabbit''s diet should be 80% high-quality hay (like Timothy hay) to keep their digestive system moving and wear down their ever-growing teeth. Overfeeding carrots or fruit can lead to obesity and painful dental disease. Stick to leafy greens like kale or romaine for their daily fresh snacks.', 'Why the ''Bugs Bunny'' diet is actually harmful to rabbits.', 'Small Pet', '🥕', 7, ARRAY['small pets','nutrition','health','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T09:40:00Z'::timestamptz, '2026-05-15T09:40:00Z'::timestamptz),
('Chinchilla Dust Baths: A Requirement', 'Chinchillas have incredibly dense fur—up to 80 hairs per follicle. If they get wet, the fur traps moisture against the skin and can''t dry properly, leading to fungal infections or rot. To stay clean, they roll in volcanic ash or ''chinchilla dust.'' This fine powder removes oils and debris. Provide a dust bath 2-3 times a week for 15 minutes to keep their coat plush and healthy.', 'Why you should never get a chinchilla wet with water.', 'Small Pet', '🛁', 6, ARRAY['small pets','grooming','health','maintenance']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T09:45:00Z'::timestamptz, '2026-05-15T09:45:00Z'::timestamptz),
('The Cost of Pet Ownership: Beyond the Adoption Fee', 'Adopting a pet is the ''cheap'' part. Annual costs for a medium dog can range from $1,000 to $2,500 including food, flea prevention, and routine vet visits. Experts recommend keeping an ''emergency fund'' of at least $1,500 specifically for unexpected health issues. Being financially prepared ensures that when a crisis happens, your focus can be on your pet''s recovery rather than the bill.', 'A breakdown of emergency funds and annual maintenance costs.', 'General', '💰', 10, ARRAY['life','finance','generic','maintenance']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T09:50:00Z'::timestamptz, '2026-05-15T09:50:00Z'::timestamptz),
('First Aid Kit Essentials for Pet Owners', 'Every pet household needs a basic first aid kit. Essential items include: self-clinging bandages (that won''t stick to fur), antiseptic wipes, a digital thermometer, tweezers (for ticks or splinters), and styptic powder to stop bleeding from a quicked nail. Keeping these in a dedicated box ensures you aren''t scrambling for supplies when your pet has a minor accident.', 'Items you should always have on hand for minor injuries.', 'General', '🩹', 9, ARRAY['safety','health','maintenance','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T09:55:00Z'::timestamptz, '2026-05-15T09:55:00Z'::timestamptz),
('Summer Safety: Protecting Paws from Hot Pavement', 'Pavement and asphalt can reach temperatures over 60°C in direct sun, which can cause second-degree burns on a dog''s paw pads in seconds. Use the ''7-second rule'': place the back of your hand on the pavement. If you can''t hold it there comfortably for 7 seconds, it''s too hot for your dog. Stick to grass, or limit walks to early mornings and late evenings when the ground has cooled.', 'How to tell if the ground is too hot for your dog''s walk.', 'Canine', '☀️', 6, ARRAY['dogs','safety','health','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T10:00:00Z'::timestamptz, '2026-05-15T10:00:00Z'::timestamptz),
('Deciphering the ''Tail Wag'': It''s Not Always Happy', 'A wagging tail isn''t a universal sign of friendliness. A high, stiff, fast wag often indicates over-stimulation or aggression, while a low, slow wag can mean insecurity. Research suggests that a wag biased toward the right side of the dog''s body typically indicates positive emotions, while a left-sided wag signals negative ones. Always look at the rest of the body—stiff muscles or pinned ears—before approaching.', 'Why direction and height matter when reading canine body language.', 'Canine', '🐕', 7, ARRAY['dogs','behavior','life','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T10:05:00Z'::timestamptz, '2026-05-15T10:05:00Z'::timestamptz),
('The ''Slow Blink'': Communicating with Your Cat', 'In the feline world, closing one''s eyes is the ultimate sign of trust. If you catch your cat looking at you, try narrowing your eyes and blinking very slowly. This is often called a ''cat kiss.'' It signals that you are not a threat. If the cat blinks back, you’ve successfully communicated affection. It’s an excellent way to bond with a new or shy cat without invading their physical space.', 'How to use eye contact to build trust with a fearful feline.', 'Feline', '👁️', 5, ARRAY['cats','behavior','life','bonding']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T10:10:00Z'::timestamptz, '2026-05-15T10:10:00Z'::timestamptz),
('Why Cats Need Horizontal and Vertical Scratchers', 'Not all cats scratch the same way. ''Vertical scratchers'' prefer to stretch their spines upward (often targeting sofa arms), while ''horizontal scratchers'' like to shred rugs or carpets. Providing both styles—a tall sisal post and a flat cardboard wedge—ensures your cat can fulfill their instinctual need to groom their claws and mark territory regardless of their postural preference.', 'Understanding individual scratching preferences to save your furniture.', 'Feline', '🛋️', 6, ARRAY['cats','behavior','setup','maintenance']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T10:15:00Z'::timestamptz, '2026-05-15T10:15:00Z'::timestamptz),
('PAR and PUR: Choosing the Right Aquarium Light', 'Photosynthetic Active Radiation (PAR) measures the amount of light available for photosynthesis. Photosynthetic Usable Radiation (PUR) measures the quality of that light. For a successful aquascape, you need high PAR at the substrate level for ''carpet'' plants. Instead of looking at watts, look for lights with a high CRI (Color Rendering Index) and check PAR charts to ensure your light can penetrate the depth of your tank.', 'Why wattage isn''t the best way to measure light for your plants.', 'Aquatic', '💡', 11, ARRAY['aquarium','plants','setup','science']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T10:20:00Z'::timestamptz, '2026-05-15T10:20:00Z'::timestamptz),
('Floating Plants: The Natural Nitrate Sponge', 'Floating plants are incredible for aquarium health because they have direct access to CO2 from the air, allowing them to grow rapidly and absorb massive amounts of nitrates. They also provide shade, which helps control algae and offers security for shy fish or shrimp. Just be sure to ''corral'' them with a floating ring so they don''t block all the light for the plants growing at the bottom.', 'Using Salvinia, Frogbit, and Duckweed to keep your water clean.', 'Aquatic', '🌿', 7, ARRAY['aquarium','plants','maintenance','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T10:25:00Z'::timestamptz, '2026-05-15T10:25:00Z'::timestamptz),
('Why Mirrors Can Be Harmful to Birds', 'Many bird owners provide mirrors as toys, but they can cause severe behavioral issues. A bird doesn''t recognize its own reflection; it sees a stranger or a potential mate. This can lead to obsessive ''courtship'' behaviors, aggression toward the owner, or extreme distress when the ''other bird'' doesn''t respond. It''s better to provide foraging toys and social interaction with real flock members or humans.', 'The psychological impact of ''imaginary'' flock members.', 'Avian', '🪞', 8, ARRAY['birds','behavior','health','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T10:30:00Z'::timestamptz, '2026-05-15T10:30:00Z'::timestamptz),
('Tail Bobbing in Birds: A Sign of Labored Breathing', 'A bird''s tail should remain relatively still as they breathe. If you notice their tail bobbing rhythmically up and down while they are perched, it is often a sign that they are using their abdominal muscles to force air through their lungs. Since birds hide illness well, tail bobbing is a serious warning sign of respiratory infection or heart issues. Consult an avian vet immediately if you see this behavior.', 'Recognizing respiratory distress before it becomes an emergency.', 'Avian', '🦜', 9, ARRAY['birds','health','safety','emergency']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T10:35:00Z'::timestamptz, '2026-05-15T10:35:00Z'::timestamptz),
('Hedgehog Anointing: The Strange Behavior Explained', 'Self-anointing is a unique hedgehog behavior where they lick a new scent, create a frothy foam in their mouth, and spread it over their quills. While it looks alarming, it is completely natural. It’s believed they do this to ''camouflage'' their scent or to use the chemicals of the new object as a deterrent for predators. If your hedgehog starts anointing, simply let them finish—it means they are exploring their world.', 'Why your hedgehog is covering itself in frothy saliva.', 'Small Pet', '🦔', 6, ARRAY['small pets','behavior','life','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T10:40:00Z'::timestamptz, '2026-05-15T10:40:00Z'::timestamptz),
('Guinea Pig ''Popcorning'': Pure Joy in Motion', 'When a guinea pig is excited, they may suddenly jump straight into the air, often twisting their bodies or kicking their legs. This is called ''popcorning.'' It''s a sign of high spirits and vitality, common during floor time or when fresh vegetables are served. If your older guinea pig stops popcorning, it might just be age, but for young cavies, it''s a great barometer for their overall happiness.', 'Understanding the sudden hops and twists of a happy cavy.', 'Small Pet', '🍿', 4, ARRAY['small pets','behavior','life','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T10:45:00Z'::timestamptz, '2026-05-15T10:45:00Z'::timestamptz),
('Pet Travel: The Crate Training Foundation', 'Whether you are moving across town or flying to a new country, a crate should be a ''safe haven,'' not a punishment. Start months in advance by feeding your pet inside the crate with the door open. Gradually increase the time they spend inside. For air travel, ensure the crate is IATA-approved and large enough for the pet to stand up and turn around completely. Familiar scents, like an old t-shirt, can help reduce anxiety during transit.', 'Ensuring your pet is safe and calm during long-distance moves.', 'General', '✈️', 10, ARRAY['travel','life','training','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T10:50:00Z'::timestamptz, '2026-05-15T10:50:00Z'::timestamptz),
('Home Hazards: Toxic Houseplants to Avoid', 'Many popular houseplants are toxic if ingested. Lilies are deadly to cats, even in small amounts (pollen or vase water), causing rapid kidney failure. Other common culprits include Sago Palms (highly toxic to dogs), Philodendrons, and Aloe Vera. If you want to keep greenery, opt for pet-safe alternatives like Spider Plants, Boston Ferns, or Areca Palms. Always check the ASPCA toxic plant list before bringing a new plant home.', 'Protecting your curious pets from common indoor greenery.', 'General', '🪴', 8, ARRAY['safety','health','life','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T10:55:00Z'::timestamptz, '2026-05-15T10:55:00Z'::timestamptz)
) AS v(title, content, summary, category, emoji, read_time_minutes, tags, thumbnail_url, is_published, author_name, view_count, created_at, updated_at)
WHERE NOT EXISTS (SELECT 1 FROM public.knowledge_articles k WHERE k.title = v.title AND coalesce(k.summary,'') = coalesce(v.summary,''));